class Calculator:
    def __init__(self):
        self._mem = 0

    def add(self, a, b):
        return a + b

    def sub(self, a, b):
        return a - b

    def mul(self, a, b):
        return a * b

    def div(self, a, b):
        if b == 0:
            raise ValueError("division by zero")
        return a / b

    def store(self, x):
        self._mem = x

    def recall(self):
        return self._mem

    def clear(self):
        self._mem = 0

